nserror probe_resource_get(const char* name, const uint8_t** data, size_t* length) {
  if (!name || !data || !length) return NSERROR_BAD_PARAMETER;
  if (!strcmp(name, "default.css")) {
    *data = probe_resource_0;
    *length = sizeof(probe_resource_0);
    return NSERROR_OK;
  }
  if (!strcmp(name, "quirks.css")) {
    *data = probe_resource_1;
    *length = sizeof(probe_resource_1);
    return NSERROR_OK;
  }
  if (!strcmp(name, "internal.css")) {
    *data = probe_resource_2;
    *length = sizeof(probe_resource_2);
    return NSERROR_OK;
  }
  if (!strcmp(name, "Messages")) {
    *data = probe_resource_3;
    *length = sizeof(probe_resource_3);
    return NSERROR_OK;
  }
  *data = NULL;
  *length = 0;
  return NSERROR_NOT_FOUND;
}
nserror probe_resource_release(const uint8_t* data) {
  if (data == probe_resource_0) return NSERROR_OK;
  if (data == probe_resource_1) return NSERROR_OK;
  if (data == probe_resource_2) return NSERROR_OK;
  if (data == probe_resource_3) return NSERROR_OK;
  return NSERROR_BAD_PARAMETER;
}
